class Solution { fun findDuplicate(paths:Array<String>):List<List<String>>{val groups=sortedMapOf<String,MutableList<String>>();for(description in paths){val parts=description.split(' ');for(i in 1 until parts.size){val open=parts[i].indexOf('(');val name=parts[i].substring(0,open);val content=parts[i].substring(open+1,parts[i].lastIndex);groups.getOrPut(content){mutableListOf()}.add(parts[0]+"/"+name)}};return groups.values.filter{it.size>1}.map{it.sorted()}} }
